// src/App.js - Root Component with React Router setup
import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import PrivateRoute from './components/PrivateRoute';
import Register from './pages/Register';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';

/**
 * App - Root component
 *
 * Routing structure:
 *   /             → redirect to /login
 *   /register     → Register page (public)
 *   /login        → Login page (public)
 *   /dashboard    → Dashboard page (PRIVATE — requires JWT)
 */
const App = () => {
  return (
    // AuthProvider wraps everything so auth state is accessible app-wide
    <AuthProvider>
      <Router>
        <Routes>

          {/* Default route: redirect root to login */}
          <Route path="/" element={<Navigate to="/login" replace />} />

          {/* Public Routes */}
          <Route path="/register" element={<Register />} />
          <Route path="/login"    element={<Login />} />

          {/* Protected Route: only accessible if user is logged in */}
          <Route
            path="/dashboard"
            element={
              <PrivateRoute>
                <Dashboard />
              </PrivateRoute>
            }
          />

          {/* Catch-all: redirect unknown paths to login */}
          <Route path="*" element={<Navigate to="/login" replace />} />

        </Routes>
      </Router>
    </AuthProvider>
  );
};

export default App;
